  enterLoanInformation(
    requestid: number,
    name: string,
    loanamount: number,
    loanpurpose: string,
    income: number,
    phonenumber: number,
    postaladdress: string,
    zipcode: number,
    email: string,
    workreferences: string,
    creditreferences: string,
    checkingaccountnumber: number,
    securitynumber: number,
  ): boolean {
    /*Definition Start*/
    let lr: LoanRequest = l({
      logic: () =>
        getRepository(LoanRequest).find(
          (x: any) =>
            l({
              logic: () => x.RequestID === requestid,
              description: "x.RequestID=requestid",
            }).build().pass,
        ),
      description: "LoanRequest.allInstance()->any(x|x.RequestID=requestid)",
    }).build().pass;
    /*Definition End*/

    /*Precondition Start*/
    const { errorMessage: preconditionErrorMessage, pass: isPreconditionPass } =
      l({
        logic: () => true,
        description: "true",
      }).build();
    if (!isPreconditionPass) {
      throw new PreconditionError(preconditionErrorMessage);
    }
    /*Precondition End*/

    /*Postcondition Start*/
    let newlr: LoanRequest;
    return l({
      execute: () => (newlr = new LoanRequest()),
      description: "newlr.oclIsNew()",
    })
      .if({
        logic: () =>
          l({
            logic: () => StandardOPs.oclIsUndefined(lr),
            description: "lr.oclIsUndefined()",
          }),
        description: "lr.oclIsUndefined()",
        then: l({
          execute: () => getRepository(LoanRequest).push(newlr),
          description: "LoanRequest.allInstance()->includes(newlr)",
